  ('lunganbraadl', 'Lunganbraadl', 'das', '', '', 'Wiener Fleischhauer-Slang', 'Lungenbratl', '[{"kategorie": "wörtlich, eigentlich", "text": "\"Lendenbraten\" (Determinativkompositum aus \"Lunge\"=\"Lende\" [abgeleitet vom lateinischen \"lumbus\"=\"Lende\", aufgrund des ähnlichen Wortklangs volkstümlich verballhornt zu \"Lunge\"] und \"Bratl\"=\"Braten\")"}, {"kategorie": "Fleischhauerjargon", "text": "\"Lungenbraten\", \"Schweins- oder Rinderfiletstück\", [[Lumpalbraadl]],  [[Lumpl]], [[Lumperl]], [[Fischerl]], [[Jungfernbraten]], [[Jungfernstückl]]"}]'::jsonb, ''),
