  ('kiifaen', 'kiifän', '', '', '', 'Grundwortschatz Wienerisch', 'kiefeln', '[{"kategorie": "wörtlich", "text": "\"an etwas nagen\" (vom mittelhochdeutschen \"kifelen\"=\"nagen\")"}, {"kategorie": "allg.", "text": "kauen, knabbern, \"mit den Zähnen kneten\", [[fieseln]]"}, {"kategorie": "fig.", "text": "\"sich mit einem Problem herumschlagen\", \"sich die Zähne an etwas ausbeißen\""}, {"kategorie": "scherzhaft für", "text": "jemandem einen [[blasen]], \"fellationieren\", jemanden oral befriedigen"}]'::jsonb, 'Dea kiifäd aun seina Zigaan wiara Hund aun sein Kauknochn!'),
