  ('marueuenkropfn', 'Marüünkropfn', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Marillenkrapfen', '[{"kategorie": "wörtlich", "text": "\"Marillenkrapfen\" (Determinativkompositum aus \"Marille\"=\"Aprikose\" und \"Krapfen\"=\"Backwerk\")"}, {"kategorie": "Kulinarik", "text": "\"Marillenkrapfen\" (kleines, rundes, mit Marillenmarmelade gefülltes, in Fett schwimmend ausgebackenes Germteiggebäck), (Deutschland): \"Berliner\" (norddeutsches Äquivalent zum Krapfen), [[Krapfen]], Vanillekrapfen, [[Faschingskrapfen]], [[Indianerkrapfen]]"}]'::jsonb, 'Ob Marüün-, Indiana- oda Vanillikropfn - aum End laundns olle in mein Bauch!'),
  ('vanillikropfn', 'Vanillikropfn', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Vanillekrapfen', '[{"kategorie": "wörtlich", "text": "\"Vanillekrapfen\" (Determinativkompositum aus \"Vanille\"=\"Vanillecreme\" und \"Krapfen\"=\"Backwerk\")"}, {"kategorie": "Kulinarik", "text": "\"Vanillekrapfen\" (kleines, rundes, mit Vanillecreme gefülltes, in Fett schwimmend ausgebackenes Germteiggebäck), (Deutschland): \"Berliner\" (norddeutsches Äquivalent zum Krapfen), [[Krapfen]], [[Marmeladekrapfen]], [[Faschingskrapfen]], [[Indianerkrapfen]]"}]'::jsonb, 'Ob Marmelade-, Indiana- oda Vanillikropfn - aum End laundns olle in mein Bauch!'),
